{
  "assessment": "Russia's economic resilience remains strong despite Western sanctions, but the -2.5% budget deficit and 6.7% inflation require fiscal tightening and a cautious monetary stance. The military situation in Ukraine is stable but demands continued resource allocation to maintain the initiative. Domestic stability is currently maintained through high repression, though the 'mixed' mood across sectors necessitates vigilant security and propaganda efforts.",
  "directives": [
    {
      "type": "set_tax",
      "target": null,
      "amount": 31.0,
      "order": "Increase total tax revenue to 31% of GDP to narrow the budget deficit."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": 100,
      "order": "Raise the policy rate by 100 basis points to combat 6.7% inflation."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 6.5,
      "sub": "military",
      "order": "Increase military spending to 6.5% of GDP to sustain operations in Ukraine."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.0,
      "sub": "security",
      "order": "Increase security spending to 2.0% of GDP to ensure domestic stability and the loyalty of the services."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.5,
      "sub": "infrastructure",
      "order": "Reduce infrastructure spending slightly to 2.5% to prioritize the war effort."
    },
    {
      "type": "media_control",
      "target": null,
      "amount": 0,
      "sub": "propaganda",
      "order": "Direct all media outlets to emphasize the necessity of the conflict and the failure of Western sanctions."
    },
    {
      "type": "repression_level",
      "target": null,
      "amount": 0.75,
      "order": "Maintain high pressure on dissent; prioritize the suppression of anti-war movements in urban centers."
    },
    {
      "type": "foreign_influence_op",
      "target": "USA",
      "amount": 0,
      "order": "Exacerbate internal political divisions and highlight the cost of aid to Ukraine."
    },
    {
      "type": "covert_op",
      "target": "UKR",
      "amount": 0,
      "sub": "sabotage",
      "order": "Target energy infrastructure and logistics hubs behind the front lines."
    }
  ],
  "cables": [
    {
      "to": "CHN",
      "private": true,
      "text": "Russia values our growing trade partnership. We are prepared to increase energy exports at stable prices in exchange for continued technological cooperation."
    },
    {
      "to": "PRK",
      "private": true,
      "text": "We acknowledge and appreciate the ongoing military-technical cooperation. Our alliance remains a cornerstone of regional security."
    },
    {
      "to": "IND",
      "private": true,
      "text": "We propose expanding the use of national currencies in our trade to bypass Western financial restrictions."
    }
  ],
  "public_statement": "The Russian economy has proven its immunity to foreign pressure, achieving 4.3% growth while our adversaries stagnate. Our Special Military Operation will continue until all objectives are met, ensuring the security of our borders and the protection of our people. We stand firm against the hegemony of the West, supported by our true partners in the Global South.",
  "detailed_report": "military"
}
